'use strict';
const KEY='mawadda-v1';
const fresh=()=>({version:1,names:['الخاطب','المخطوبة'],answers:[{},{}],reviews:{},position:[1,1],updated:null});
let state=fresh(),storageOK=true,person=0,filter='all',categoryFilter='all',search='';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function valid(s){if(!s||s.version!==1||!Array.isArray(s.names)||s.names.length!==2||!s.names.every(n=>typeof n==='string'&&n.length<=60)||!Array.isArray(s.answers)||s.answers.length!==2||!s.reviews||typeof s.reviews!=='object'||!Array.isArray(s.position)||s.position.length!==2||!s.position.every(n=>Number.isInteger(n)&&n>=1&&n<=150))return false;for(const group of s.answers){if(!group||typeof group!=='object'||Array.isArray(group))return false;for(const [id,a] of Object.entries(group)){const q=questions[Number(id)-1];if(!q||!a||typeof a!=='object'||typeof a.text!=='string'||a.text.length>10000||typeof a.choice!=='string'||!(a.choice===''||a.choice==='أخرى'||q.options?.includes(a.choice))||![1,2,3].includes(a.importance)||typeof a.skip!=='boolean'||typeof a.flag!=='boolean')return false;}}for(const [id,r]of Object.entries(s.reviews)){if(!questions[Number(id)-1]||!r||!['','agree','partial','different'].includes(r.status)||typeof r.note!=='string'||r.note.length>10000)return false;}return true;}
try{const saved=localStorage.getItem(KEY);if(saved){const s=JSON.parse(saved);if(valid(s))state=s;else storageOK=false;}}catch(e){storageOK=false;}
function save(){state.updated=new Date().toISOString();try{localStorage.setItem(KEY,JSON.stringify(state));storageOK=true;}catch(e){storageOK=false;toast('تعذّر الحفظ على المتصفح. صدّر نسخة احتياطية من صفحة الحفظ.');}const el=document.querySelector('#saveStatus');if(el)el.textContent=storageOK?'✓ حُفظ على هذا المتصفح':'تعذّر الحفظ — صدّر نسخة';}
function toast(t){const e=document.querySelector('#toast');e.textContent=t;e.style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>e.style.display='none',3500);}
function answer(p,id){return state.answers[p][id]||{choice:'',text:'',importance:1,skip:false,flag:false};}
function answered(a){return !a.skip&&!!(a.text.trim()||(a.choice&&a.choice!=='أخرى'));}
function count(p,c){return questions.filter(q=>(c===undefined||q.category===c)&&answered(answer(p,q.id))).length;}
const importance=['','تفضيل شخصي','قابل للنقاش','أساسي عندي'];
function evaluation(q){const a=answer(0,q.id),b=answer(1,q.id),r=state.reviews[q.id];if(!answered(a)||!answered(b))return {status:'incomplete'};if(r?.status)return {status:r.status,manual:true,weight:Math.max(a.importance,b.importance)};if(q.auto&&a.choice&&b.choice&&a.choice!=='أخرى'&&b.choice!=='أخرى'&&!a.choice.includes('شفهيًا')&&!b.choice.includes('شفهيًا'))return {status:a.choice===b.choice?'agree':'different',manual:false,weight:Math.max(a.importance,b.importance)};return {status:'pending'};}
function metrics(list=questions){const ev=list.map(q=>evaluation(q)),rated=ev.filter(e=>['agree','partial','different'].includes(e.status)),den=rated.reduce((s,e)=>s+e.weight,0);return {rated:rated.length,paired:ev.filter(e=>e.status!=='incomplete').length,agree:ev.filter(e=>e.status==='agree').length,different:ev.filter(e=>e.status==='different').length,pending:ev.filter(e=>e.status==='pending').length,score:den?Math.round(rated.reduce((s,e)=>s+e.weight*({agree:1,partial:.5,different:0}[e.status]),0)/den*100):null};}
function progress(n,total=150){return `<div class="track"><i style="width:${n/total*100}%"></i></div>`;}
function home(){const n=count(0)+count(1);return `<section class="hero"><div><div class="eyebrow">بداية جميلة، تبدأ بسؤال صادق</div><h1>قبل أن نشارك الحياة،<br><em>لنفهم بعضنا أكثر.</em></h1><p>مساحة هادئة لكما، تفتح أبواب الحديث عن القيم والأحلام وتفاصيل الحياة. خذا وقتكما… كل إجابة خطوة نحو بداية أوضح.</p><div class="actions"><a class="btn primary" href="#questions">${n?'نكمل رحلتنا':'نبدأ رحلة التعارف'} <span>←</span></a><a class="btn" href="#results">مساحة المقارنة</a></div><p class="muted" style="margin-top:15px">✓ حفظ تلقائي على متصفحك &nbsp; · &nbsp; على راحتكما، دون مؤقّت</p></div><div class="hero-art" aria-hidden="true"><div class="art-card"><div class="rings">○○</div><h3>أنا، وأنت… ونحن</h3><p>ليس المطلوب أن نتشابه في كل شيء،<br>بل أن نفهم ما يهمّ كلًا منّا.</p></div><span class="art-tag">مساحة للحوار، وليست للحكم</span></div></section><div class="stats"><div class="stat"><span class="label">↗</span><strong>150</strong><p>سؤالًا يفتح بابًا للحديث</p></div><div class="stat"><span class="label">◇</span><strong>15</strong><p>محورًا لحياة مشتركة</p></div><div class="stat"><span class="label">◌</span><strong>${Math.round(n/300*100)}٪</strong><p>من إجاباتكما مكتملة · ${n} / 300</p></div></div><div class="section-head"><h2>كل جانب يستحق أن نحكي عنه</h2><p>ابدآ بما يريحكما · 10 أسئلة لكل محور</p></div><div class="grid">${categories.map((c,i)=>`<button class="topic" data-category="${i}"><span class="num">${String(i+1).padStart(2,'0')}</span><h3>${c}</h3><p>${count(0,i)+count(1,i)} من 20 إجابة للطرفين <span style="float:left">←</span></p>${progress(count(0,i)+count(1,i),20)}</button>`).join('')}</div><div class="callout"><strong>كيف نبدأ؟</strong><p>اختاروا ملف الخاطب أو المخطوبة، وأجيبوا بشكل مستقل. بعدها افتحوا المقارنة سوا، وناقشوا ما وراء الإجابات. جلسة من 10 إلى 15 سؤالًا تكفي.</p></div><p class="muted">الملفان على نفس الجهاز، وليسا حسابين محميين. البيانات لا تُرسل لخادم أو لشريكك تلقائيًا. يمكنكما تبادل ملف إجابات عبر التصدير والاستيراد باختياركما.</p>`;}
function questionnaire(){const q=questions[state.position[person]-1],a=answer(person,q.id),n=count(person);return `<div class="pagehead"><div class="eyebrow">خطوة بخطوة، وعلى راحتك</div><h1>مساحة إجابتك</h1><p>جاوب بصدق، مش بالإجابة اللي تتوقع الطرف الآخر يحب يسمعها.</p></div><div class="workspace"><aside class="sidebar" aria-label="محاور الأسئلة">${categories.map((c,i)=>`<button data-category="${i}" class="${q.category===i?'selected':''}">${esc(c)} <span>${count(person,i)}/10</span></button>`).join('')}</aside><section><div class="card"><div class="tabs" aria-label="اختيار الطرف">${state.names.map((name,i)=>`<button data-person="${i}" class="${person===i?'selected':''}" aria-pressed="${person===i}">${esc(name)}</button>`).join('')}</div><div class="qhead"><span>${n} من 150 إجابة</span><span id="saveStatus" class="saved">${storageOK?'✓ حفظ تلقائي على هذا المتصفح':'الحفظ غير متاح — صدّر نسخة'}</span></div>${progress(n)}<div class="qhead"><span>${esc(categories[q.category])}</span><span>السؤال ${q.id} / 150</span></div><h2 class="qtext">${esc(q.text)}</h2>${q.category===11?'<p class="muted">شارك ما ترتاح لمشاركته. يمكنك ترك التفاصيل الحساسة لحوار خاص.</p>':''}${q.options?`<div class="options" role="radiogroup" aria-label="خيارات الإجابة">${[...q.options,'أخرى'].map(v=>`<label class="option"><input type="radio" name="choice" value="${esc(v)}" ${a.choice===v?'checked':''}>${esc(v)}</label>`).join('')}</div>`:''}<label class="field" for="answerText">${q.options?'وضّح إجابتك أو اكتب خيارك الآخر':'إجابتك'} ${q.options?'(اختياري، ومطلوب عند اختيار أخرى)':''}</label><textarea id="answerText" maxlength="10000" placeholder="احكِ بطريقتك… مثال من حياتك يساعد على فهمك أكثر.">${esc(a.text)}</textarea><label class="field">أهمية الموضوع بالنسبة إليك</label><div class="importance">${[3,2,1].map(i=>`<label><input type="radio" name="importance" value="${i}" ${a.importance===i?'checked':''}> ${importance[i]}</label>`).join('')}</div><div class="actions"><label class="check"><input id="flag" type="checkbox" ${a.flag?'checked':''}> أريد مناقشة هذا السؤال</label><button class="btn small" id="skip">${a.skip?'إلغاء التأجيل':'أؤجل الإجابة'}</button>${a.skip?'<span class="badge amber">مؤجّل · لا يدخل في التقييم</span>':''}</div><div class="qnav"><button class="btn" id="prev" ${q.id===1?'disabled':''}>→ السابق</button><button class="btn primary" id="next">${q.id===150?'الانتقال إلى المقارنة':'التالي ←'}</button></div><div class="dots" aria-label="أسئلة المحور">${questions.filter(x=>x.category===q.category).map(x=>`<button data-question="${x.id}" aria-label="السؤال ${x.id}${answered(answer(person,x.id))?'، تمت الإجابة':''}" class="${answered(answer(person,x.id))?'done':''} ${x.id===q.id?'current':''}">${x.id}</button>`).join('')}</div></div><p class="muted">يمكن تعديل الإجابات بأي وقت. تعديل إجابة يلغي تقييم الحوار السابق لهذا السؤال حتى تراجعوه من جديد.</p></section></div>`;}
const labels={agree:'متوافق',partial:'اتفاق جزئي',different:'يحتاج حوارًا',pending:'بانتظار المقارنة معًا',incomplete:'بانتظار إجابة الطرفين'};
function answerView(a){return a.skip?'مؤجّلة':!answered(a)?'لم تتم الإجابة بعد':[a.choice,a.text].filter(Boolean).join('\n');}
function results(){const m=metrics(),critical=questions.filter(q=>evaluation(q).status==='different'&&Math.max(answer(0,q.id).importance,answer(1,q.id).importance)===3).length;return `<div class="pagehead"><div class="eyebrow">نفهم الاختلاف، ونبني الاتفاق</div><h1>صورتنا، جنبًا إلى جنب</h1><p>التشابه بداية للحوار. والتفاصيل وراء الإجابة أهم من أي نسبة.</p></div><div class="result-grid"><div class="card scorecard"><span class="muted" style="color:#d3dfd3">مؤشر التوافق الوصفي ${m.rated<150?'· نتيجة جزئية':''}</span><div class="score">${m.score===null?'—':m.score+'٪'}</div><p>${m.rated?`مبني على ${m.rated} سؤالًا قابلًا للتقييم من أصل 150.`:'سيظهر بعد وجود إجابات قابلة للمقارنة للطرفين.'}</p><p style="font-size:12px;margin:0">مؤشر تنظيمي غير معتمد علميًا، وليس تنبؤًا بنجاح الزواج أو توصية بقرار.</p></div><div class="card"><h3>أين وصل الحوار؟</h3><p>${m.paired} سؤالًا أجاب عنه الطرفان · ${m.pending} بانتظار تقييمكما</p><div class="actions"><span class="badge">${m.agree} متوافق</span><span class="badge amber">${m.different} يحتاج حوارًا</span></div><p style="margin-top:15px;font-size:12px">${critical?`${critical} اختلافات في أمور أساسية: ابدآ بها حتى لو كان المؤشر العام مرتفعًا.`:'حددا أهمية المواضيع حتى تظهر الأولويات بوضوح.'}</p><button class="btn small" id="criticalFilter">عرض الاختلافات الأساسية</button></div></div><details class="method card"><summary>كيف نحسب المقارنة؟ منهجية واضحة</summary><p>للخيارات المحددة: نفس الخيار = توافق، واختلاف الخيار = يحتاج حوارًا؛ هذا لا يعني أن اختلاف الأدوار أو الاحتياجات مشكلة. يمكنكما تغيير التقييم بعد النقاش. النصوص الحرة، و«أخرى»، والإفصاحات الصحية والمالية لا تُقيّم آليًا.</p><p>بعد النقاش حددا: متوافق (1)، اتفاق جزئي (0.5)، يحتاج حوارًا (0). نستخدم الأعلى من أهمية الطرفين: أساسي (3)، قابل للنقاش (2)، تفضيل (1). المؤشر = مجموع الدرجة × الوزن ÷ مجموع الأوزان × 100. الأسئلة غير المكتملة أو غير المقيّمة مستبعدة، ولا تُحسب صفرًا. حجم العينة ظاهر دائمًا.</p><p>أي تعديل بالإجابة يلغي تقييم الحوار السابق. تطابق الخيارات قد يخفي اختلافًا بالملاحظات؛ اقرأوا الشرح قبل اعتماد النتيجة.</p></details>${m.rated?`<div class="card"><h3>التوافق حسب المحور</h3>${categories.map((c,i)=>{const x=metrics(questions.filter(q=>q.category===i));return `<div class="chartrow"><span>${c}<small style="display:block;color:#888">${x.rated}/10 مقيّمة</small></span>${progress(x.score||0,100)}<strong>${x.score===null?'—':x.score+'٪'}</strong></div>`;}).join('')}</div>`:''}<div class="section-head"><h2>الإجابات والاتفاقات</h2><div class="actions"><button class="btn small" id="print">طباعة / حفظ PDF</button><button class="btn small" data-export="all">تصدير النتائج</button></div></div><div class="tools"><input id="search" type="search" value="${esc(search)}" placeholder="ابحث في نص السؤال…" aria-label="البحث في الأسئلة"><select id="categoryFilter" aria-label="تصفية حسب المحور"><option value="all">كل المحاور</option>${categories.map((c,i)=>`<option value="${i}" ${String(i)===categoryFilter?'selected':''}>${c}</option>`).join('')}</select><select id="statusFilter" aria-label="تصفية حسب الحالة">${[['all','كل الحالات'],['agree','متوافق'],['partial','اتفاق جزئي'],['different','يحتاج حوارًا'],['critical','اختلافات أساسية'],['pending','بانتظار المقارنة'],['flag','للمناقشة'],['incomplete','غير مكتملة']].map(([v,l])=>`<option value="${v}" ${filter===v?'selected':''}>${l}</option>`).join('')}</select></div><div id="resultList">${resultList()}</div>`;}
function resultList(){const list=questions.filter(q=>{const e=evaluation(q);return(categoryFilter==='all'||String(q.category)===categoryFilter)&&q.text.includes(search)&&(filter==='all'||filter===e.status||filter==='critical'&&e.status==='different'&&e.weight===3||filter==='flag'&&(answer(0,q.id).flag||answer(1,q.id).flag));});if(!list.length)return '<div class="empty"><h3>لا توجد أسئلة ضمن هذا الاختيار</h3><p>جرّب تغيير الفلاتر أو أكمل الإجابات أولًا.</p></div>';return list.map(q=>{const e=evaluation(q),r=state.reviews[q.id]||{status:'',note:''};return `<article class="card result-item"><span class="badge ${e.status==='different'?'amber':['pending','incomplete'].includes(e.status)?'gray':''}">${labels[e.status]}</span><span class="muted"> · ${e.manual?'تقييمكما بعد الحوار':e.status==='agree'||e.status==='different'?'مقارنة الخيارات':'بدون تقييم آلي'}</span><h3>${q.id}. ${esc(q.text)}</h3><div class="compare">${[0,1].map(p=>`<div class="answer"><strong>${esc(state.names[p])} · ${importance[answer(p,q.id).importance]}</strong>${esc(answerView(answer(p,q.id)))}</div>`).join('')}</div><div class="review no-print"><label for="review-${q.id}">تقييمكما بعد الحوار</label><select id="review-${q.id}" data-review="${q.id}" ${e.status==='incomplete'?'disabled':''}><option value="">بدون تقييم يدوي</option>${['agree','partial','different'].map(s=>`<option value="${s}" ${r.status===s?'selected':''}>${labels[s]}</option>`).join('')}</select><button class="btn small" data-question="${q.id}">تعديل الإجابة</button></div><label class="field" for="note-${q.id}">اتفاقنا / خطوة المتابعة</label><textarea id="note-${q.id}" data-note="${q.id}" maxlength="10000" placeholder="ماذا اتفقنا؟ وما الذي نحتاج مناقشته لاحقًا؟">${esc(r.note)}</textarea></article>`;}).join('');}
function settings(){return `<div class="pagehead"><div class="eyebrow">بياناتكما تحت اختياركما</div><h1>الحفظ والملفات</h1><p>حفظ تلقائي محلي، مع نسخة احتياطية وقت ما تحتاجوا.</p></div><div class="settings-grid"><div class="card"><h3>ملفّا التعارف</h3>${state.names.map((n,i)=>`<label class="field" for="name-${i}">${i?'اسم المخطوبة':'اسم الخاطب'} (اختياري)</label><input type="text" id="name-${i}" data-name="${i}" maxlength="60" value="${esc(n)}">`).join('')}<p class="muted" style="margin-top:15px">يمكن استخدام اسم مستعار. التبديل بين الملفين لا يحتاج كلمة مرور؛ كل من يستخدم هذا المتصفح يستطيع الاطلاع عليهما.</p></div><div class="card"><h3>نسخة احتياطية ونقل الإجابات</h3><p class="muted">صدّر كل البيانات للاحتفاظ بها، أو ملف طرف واحد لتبادله باختيارك. الملف يحتوي إجابات واضحة غير مشفّرة.</p><div class="actions"><button class="btn primary" data-export="all">تصدير نسخة كاملة</button><button class="btn" id="import">استيراد ملف</button></div><div class="actions" style="margin-top:15px"><button class="btn small" data-export="0">تصدير ${esc(state.names[0])}</button><button class="btn small" data-export="1">تصدير ${esc(state.names[1])}</button></div><p class="muted" style="margin-top:16px">استيراد طرف واحد يستبدل ملفه فقط ويلغي تقييمات الحوار القديمة. استيراد نسخة كاملة يستبدل كل البيانات بعد تأكيدك. لا توجد مزامنة سحابية أو إرسال تلقائي.</p></div></div><div class="callout"><strong>${storageOK?'✓ الحفظ المحلي متاح':'تعذّر قراءة أو حفظ بيانات المتصفح'}</strong><p>الحفظ مرتبط بهذا المتصفح وهذا الجهاز. حذف بيانات الموقع أو استخدام التصفح الخاص قد يفقد الإجابات. احتفظ بنسخة احتياطية.</p><p class="muted">آخر حفظ: ${state.updated?esc(new Date(state.updated).toLocaleString('ar-AE')):'لم تبدأ الإجابات بعد'}</p></div><div class="card"><h3>بداية جديدة</h3><p class="muted">حذف الإجابات والملاحظات والأسماء المحفوظة على هذا المتصفح فقط. الملفات المصدّرة لا تُحذف.</p><button class="btn danger" id="reset">حذف جميع البيانات المحلية</button></div>`;}
function navigateQuestion(id){state.position[person]=id;save();if(location.hash==='#questions')render();else location.hash='questions';window.scrollTo(0,0);}
function render(){const route=location.hash.slice(1)||'home';document.querySelectorAll('nav a').forEach(a=>{a.classList.toggle('active',a.hash==='#'+route);if(a.hash==='#'+route)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});document.querySelector('#app').innerHTML=({home,questions:questionnaire,results,settings}[route]||home)();bind();}
function updateAnswer(prop,value){const id=state.position[person],a={...answer(person,id),[prop]:value};if(prop==='text'||prop==='choice')a.skip=false;state.answers[person][id]=a;delete state.reviews[id];save();}
function download(which){const data=which==='all'?{kind:'mawadda-full',data:state}:{kind:'mawadda-person',person:Number(which),data:{...fresh(),names:[...state.names],answers:[which==='0'?state.answers[0]:{},which==='1'?state.answers[1]:{}]}};const blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`mawadda-${which==='all'?'backup':'person-'+which}-${new Date().toISOString().slice(0,10)}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('تم تجهيز ملف البيانات للتنزيل');}
function bind(){document.querySelectorAll('[data-category]').forEach(b=>b.onclick=()=>navigateQuestion(+b.dataset.category*10+1));document.querySelectorAll('[data-question]').forEach(b=>b.onclick=()=>navigateQuestion(+b.dataset.question));document.querySelectorAll('[data-person]').forEach(b=>b.onclick=()=>{person=+b.dataset.person;render();});document.querySelectorAll('[name=choice]').forEach(e=>e.onchange=()=>{updateAnswer('choice',e.value);render();});document.querySelectorAll('[name=importance]').forEach(e=>e.onchange=()=>updateAnswer('importance',+e.value));const ta=document.querySelector('#answerText');if(ta)ta.oninput=()=>updateAnswer('text',ta.value);const flag=document.querySelector('#flag');if(flag)flag.onchange=()=>updateAnswer('flag',flag.checked);const skip=document.querySelector('#skip');if(skip)skip.onclick=()=>{updateAnswer('skip',!answer(person,state.position[person]).skip);render();};const next=document.querySelector('#next');if(next)next.onclick=()=>state.position[person]===150?location.hash='results':navigateQuestion(state.position[person]+1);const prev=document.querySelector('#prev');if(prev)prev.onclick=()=>navigateQuestion(state.position[person]-1);document.querySelectorAll('[data-export]').forEach(b=>b.onclick=()=>download(b.dataset.export));document.querySelectorAll('[data-name]').forEach(el=>el.onchange=()=>{state.names[+el.dataset.name]=el.value.trim()||(+el.dataset.name?'المخطوبة':'الخاطب');save();render();});['categoryFilter','statusFilter','search'].forEach(id=>{const e=document.querySelector('#'+id);if(e)e[id==='search'?'oninput':'onchange']=()=>{if(id==='categoryFilter')categoryFilter=e.value;if(id==='statusFilter')filter=e.value;if(id==='search')search=e.value;document.querySelector('#resultList').innerHTML=resultList();bindResults();};});const cf=document.querySelector('#criticalFilter');if(cf)cf.onclick=()=>{filter='critical';render();document.querySelector('#statusFilter').scrollIntoView({behavior:'smooth',block:'center'});};const print=document.querySelector('#print');if(print)print.onclick=()=>{if(confirm('سيشمل التقرير كل الإجابات والاتفاقات، بما فيها التفاصيل الحساسة. هل تريد فتح الطباعة؟')){filter='all';categoryFilter='all';search='';render();window.print();}};const imp=document.querySelector('#import');if(imp)imp.onclick=()=>document.querySelector('#importFile').click();const reset=document.querySelector('#reset');if(reset)reset.onclick=()=>{if(confirm('هل تريد حذف جميع الإجابات والأسماء والاتفاقات من هذا المتصفح؟ لا يمكن التراجع دون نسخة احتياطية.')){state=fresh();person=0;save();render();toast('تم حذف البيانات المحلية');}};bindResults();}
function bindResults(){document.querySelectorAll('[data-review]').forEach(el=>el.onchange=()=>{const id=el.dataset.review;state.reviews[id]={...(state.reviews[id]||{note:''}),status:el.value};save();const y=scrollY;render();window.scrollTo(0,y);});document.querySelectorAll('[data-note]').forEach(el=>el.oninput=()=>{const id=el.dataset.note;state.reviews[id]={...(state.reviews[id]||{status:''}),note:el.value};save();});document.querySelectorAll('#resultList [data-question]').forEach(b=>b.onclick=()=>navigateQuestion(+b.dataset.question));}
document.querySelector('#importFile').onchange=async event=>{const file=event.target.files[0];event.target.value='';if(!file)return;try{if(file.size>8000000)throw Error();const obj=JSON.parse(await file.text());if(!['mawadda-full','mawadda-person'].includes(obj.kind)||!valid(obj.data)||obj.kind==='mawadda-person'&&![0,1].includes(obj.person))throw Error();const label=obj.kind==='mawadda-full'?'كل بياناتكما':`إجابات ${obj.person===0?'الخاطب':'المخطوبة'} فقط`;if(!confirm(`سيستبدل هذا الملف ${label}. احتفظ بنسخة من بياناتك الحالية أولًا. هل تريد المتابعة؟`))return;if(obj.kind==='mawadda-full')state=obj.data;else{state.answers[obj.person]=obj.data.answers[obj.person];state.names[obj.person]=obj.data.names[obj.person];state.reviews={};}save();render();toast('تم استيراد البيانات بنجاح');}catch(e){toast('الملف غير صالح. اختر ملف JSON مصدّرًا من مَوَدّة.');}};
window.addEventListener('hashchange',()=>{render();window.scrollTo(0,0);});render();
